sed -i 's/showUpstoxWebView = true/val redirectUri = sessionManager.upstoxRedirectUri.takeIf { it.isNotBlank() } ?: "https:\/\/application-beige-psi.vercel.app\/oauth"\n                                val loginUrl = com.example.util.UpstoxAuthHelper.buildLoginUrl(upstoxApiKey, redirectUri, state = "upstox")\n                                try {\n                                    val intent = android.content.Intent(android.content.Intent.ACTION_VIEW, android.net.Uri.parse(loginUrl))\n                                    context.startActivity(intent)\n                                    onDismiss()\n                                } catch (e: Exception) {\n                                    localErrorMsg = "Failed to open browser"\n                                }/g' app/src/main/java/com/example/ui/components/BrokerConnectDialog.kt

